var o=[{title:`Como funcionam os intervalos`,text:`Um intervalo de trabalho aumenta a respiração e a carga de trabalho, e o intervalo de recuperação permite-lhe recuperar em parte ou quase totalmente. Pode ajustar ambos. Os intervalos podem ser aeróbicos, como caminhada rápida alternada com caminhada fácil, ou mais difíceis, como um esforço rápido de bicicleta seguido de pedalada fácil.`},{title:`Comece abaixo do esforço máximo`,text:`Se está a começar a fazer exercício, pode alternar um minuto de caminhada rápida com dois minutos de caminhada confortável durante seis rondas. Um corredor experiente pode usar esforços mais rápidos com descanso mais longo. A velocidade de trabalho certa depende do seu nível e do exercício, por isso uma proporção de tempo, por si só, não diz quão difícil é o trabalho para o seu corpo.`},{title:`A duração da recuperação depende do objetivo`,text:`As recuperações mais longas mantêm a velocidade e a qualidade do movimento altas nas repetições intensas. As recuperações mais curtas tornam a sessão mais contínua e podem aumentar a exigência global para o coração e os pulmões, mas se forem demasiado curtas, a qualidade cai depressa. Defina o trabalho e o descanso para corresponderem ao objetivo de condicionamento que tem em mente.`},{title:`Controle a carga total`,text:`Aqueça sempre de forma gradual e termine com algo mais fácil. Aumente a quantidade total de trabalho em intervalos antes de tornar os intervalos muito mais difíceis. Se a sua postura de caminhada, a mecânica de corrida ou a coordenação com a corda de saltar começar a desfazer-se, faça uma recuperação mais longa, baixe a intensidade ou termine a sessão.`},{title:`Usar o TrainUp`,text:`O temporizador de descanso e o temporizador de manutenção mantêm os seus intervalos a horas e, depois do treino, avalia o esforço da sessão de 1 a 10. Mais difícil não é automaticamente melhor. Quando gera de novo o plano, este fica mais fácil se 2 dos seus últimos 3 treinos tiverem sido muito difíceis (RPE 9 ou mais) ou concluídos em menos de 60%, e só fica um passo mais difícil se os últimos 4 tiverem sido fáceis e completos. Se precisar de menos impacto, a bicicleta ou a marcha rápida também funcionam como intervalos.`}];var i=[{label:`ACE: como desenhar intervalos de alta intensidade`,url:`https://www.acefitness.org/continuing-education/certified/may-2021/7844/how-to-use-the-ace-ift-model-to-design-effective-hiit-workouts/`},{label:`CDC: medir a intensidade da atividade e o teste da conversa`,url:`https://www.cdc.gov/physicalactivity/basics/measuring/index.html`},{label:`Recomendações do CDC sobre atividade física para adultos`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var s={sections:o,sources:i};export{s as default,o as sections,i as sources};